// PHASE 1: pick the highest-quality engine this specific look actually supports,
// instead of hardcoding avatar_v and hoping. Avoids silent 400s / quality mismatches.
const upstream = $('Select Avatar + Generate Job ID1').item.json;
const lookResp = $input.first().json;
const lookData = lookResp.data || lookResp;
const supportedEngines = lookData.supported_api_engines || lookData.supported_engines || [];

let engine;
let expressiveness;

if (supportedEngines.includes('avatar_v')) {
  engine = { type: 'avatar_v' };
  // expressiveness is Avatar IV-only; including it with avatar_v throws a validation error, so it's deliberately omitted here.
} else if (supportedEngines.includes('avatar_iv')) {
  engine = { type: 'avatar_iv' };
  expressiveness = 'high';
} else {
  throw new Error(`ENGINE_MISMATCH: avatar_id=${upstream.avatarId} does not support avatar_v or avatar_iv. supported_api_engines=${JSON.stringify(supportedEngines)}. Re-check this look in the HeyGen dashboard or drop it from config.avatarIds.`);
}

const heygenPayload = {
  type: 'avatar',
  avatar_id: upstream.avatarId,
  script: upstream.script,
  voice_id: upstream.voiceId,
  resolution: '1080p',
  aspect_ratio: '9:16',
  engine,
  motion_prompt: upstream.motionPrompt,
  enhance_custom_motion_prompt: true,
  caption: { file_format: 'srt', style: 'default' },
  callback_id: upstream.jobId,
  callback_url: 'https://tavlidiamonds.app.n8n.cloud/webhook/heygen-webhook'
};
if (expressiveness) heygenPayload.expressiveness = expressiveness;

return [{ json: { ...upstream, engineUsed: engine.type, heygenPayload } }];

const config = {
  avatarIds: [
    'f989f314422b4fbaa559e07c5cbbd17b',
    'f2eb1a9e63114833a92e80cf48321987',
    '274515c4e08a4c4689731a450caf9faa',
    '3591b4a4fd2c40698f7e0e06304fa286'
  ],
  accountIds: [
    '6a184670312a16c3f0256c7c_TrGytdd80tTYeMqrGW9e_813347731859277_page',
    '6a1846982bbb6fbb330688e3_TrGytdd80tTYeMqrGW9e_000Y4eMNplxtiH9XHEGPNPUyqvmATxc0n1_business',
    '6a196a8576455473847ec689_TrGytdd80tTYeMqrGW9e_UCztQtixZp-kIV-0lo9BMRtg_profile',
    '6a18470d530b7464136cf8dc_TrGytdd80tTYeMqrGW9e_882987208099842105_profile'
  ],
  voiceId: '59If0zDReQDrJKgWgStP',
  locationId: 'TrGytdd80tTYeMqrGW9e',
  // PHASE 1: rotating pool of natural-language motion directions.
  // HeyGen never received motion guidance before this — this is the primary fix for the 'static' complaint.
  motionPrompts: [
    'speaks with quiet, deliberate confidence; subtle hand gestures land on key words; natural pauses between thoughts',
    'relaxed, upright posture; a slight head tilt when making a point; calm, warm delivery throughout',
    'leans in gently during the opening line; an open-handed gesture on the closing call to action; unhurried pacing',
    'poised and composed; minimal but natural gesture; steady eye contact with the camera throughout'
  ]
};

const input = $input.first().json;
return [{ json: { ...input, config } }];

const raw = $input.first().json.text;
const configState = $('TAVLI Master Configuration1').item.json;
const attemptCount = configState.attemptCount || 1;

let parsed;
try {
  parsed = JSON.parse(raw.trim());
} catch (e) {
  const jsonMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    try { parsed = JSON.parse(jsonMatch[1].trim()); } catch (e2) {}
  }
  if (!parsed) {
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    if (start !== -1 && end !== -1 && end > start) {
      try { parsed = JSON.parse(raw.substring(start, end + 1)); } catch (e3) {}
    }
  }
}

let valid = true;
let errorReason = '';

if (!parsed) {
  valid = false;
  errorReason = 'LLM did not return valid JSON';
} else if (!parsed.script || typeof parsed.script !== 'string' || !parsed.script.trim()) {
  valid = false;
  errorReason = 'Schema: script missing or empty';
} else if (!parsed.caption || typeof parsed.caption !== 'string' || !parsed.caption.trim()) {
  valid = false;
  errorReason = 'Schema: caption missing or empty';
} else if (!parsed.cta || typeof parsed.cta !== 'string' || !parsed.cta.trim()) {
  valid = false;
  errorReason = 'Schema: cta missing or empty';
} else if (!Array.isArray(parsed.hashtags) || parsed.hashtags.length === 0) {
  valid = false;
  errorReason = 'Schema: hashtags must be a non-empty array';
} else {
  const script = parsed.script.trim();
  const wordCount = script.split(/\s+/).filter(w => w.length > 0).length;
  if (wordCount < 60 || wordCount > 90) {
    valid = false;
    errorReason = `Word count validation failed: ${wordCount} words (required: 60-90)`;
  }
}

if (!valid) {
  return [{ json: { valid: false, errorReason, attemptCount, config: configState.config } }];
}

const script = parsed.script.trim();
const hashtagStr = parsed.hashtags.join(' ');
const postText = `${parsed.caption}\n\n${parsed.cta}\n\n${hashtagStr}`.trim();
const wordCount = script.split(/\s+/).filter(w => w.length > 0).length;

return [{ json: { valid: true, script, postText, caption: parsed.caption, cta: parsed.cta, hashtags: parsed.hashtags, wordCount, attemptCount, config: configState.config } }];

const currentAttempt = $input.first().json.attemptCount || 1;
const newAttempt = currentAttempt + 1;
return [{ json: { attemptCount: newAttempt, errorReason: $input.first().json.errorReason } }];

const data = $('Parse + Validate Content1').item.json;
const config = data.config;
const attemptCount = data.attemptCount || 1;

const accountIds = config.accountIds;
const voiceId = config.voiceId;
const motionPrompts = config.motionPrompts || [];

// PHASE 2: pool of selectable looks now comes from the tavli_looks Data Table
// (populated by the Look Factory workflow), not a hardcoded array. Falls back to
// the original 4 seed avatars only if the table is empty/missing, so the daily
// pipeline never goes idle waiting on Look Factory to be run.
const queriedRows = $('Data Table: Get Active Looks').all().map(i => i.json);
let pool = [];
for (const row of queriedRows) {
  if (row.look_id) {
    pool.push({ avatarId: row.look_id, sceneTag: row.scene_tag || 'unspecified' });
  }
}
if (pool.length === 0) {
  pool = config.avatarIds.map(id => ({ avatarId: id, sceneTag: 'seed' }));
}

const chosen = pool[Math.floor(Math.random() * pool.length)];
const avatarId = chosen.avatarId;
const sceneTag = chosen.sceneTag;
const motionPrompt = motionPrompts.length
  ? motionPrompts[Math.floor(Math.random() * motionPrompts.length)]
  : '';
const jobId = 'tavli_' + Date.now().toString(36) + '_' + Math.random().toString(36).substring(2, 8);
const now = new Date().toISOString();

const payload = {
  job_id: jobId,
  post_text: data.postText,
  account_ids: accountIds,
  status: 'CREATING',
  attempt_count: attemptCount,
  scene_tag: sceneTag,
  created_at: now,
  updated_at: now
};

return [{ json: {
  key: `tavli:job:${jobId}`,
  value: JSON.stringify(payload),
  jobId,
  script: data.script,
  avatarId,
  sceneTag,
  voiceId,
  motionPrompt,
  postText: data.postText,
  accountIds,
  attemptCount
} }];

const originalRow = $input.first().json;
const originalVal = originalRow.value || originalRow.json?.value || '{}';
const response = $('Create HeyGen Video (with Idempotency-Key)1').item.json;
let job = {};
try { job = JSON.parse(originalVal); } catch(e) {}

const videoId = response.data ? response.data.video_id : '';
const updatedRecord = {
  ...job,
  video_id: videoId,
  status: 'GENERATED',
  updated_at: new Date().toISOString()
};

const jobId = job.job_id || $('Select Avatar + Generate Job ID1').item.json.jobId;
return [{ json: {
  key: `tavli:job:${jobId}`,
  value: JSON.stringify(updatedRecord),
  aliasKey: `tavli:video:${videoId}`,
  aliasValue: JSON.stringify({ job_id: jobId, created_at: new Date().toISOString() }),
  jobId,
  videoId
} }];

// --- Webhook Verification & Parsing ---
const crypto = require('crypto');

// Leave empty ('') if HeyGen webhook signature verification is not enabled.
const WEBHOOK_SECRET = '';

const item = $input.first().json;
const headers = item.headers || {};
const rawBody = item.rawBody;
const body = item.body || item;

// Perform HMAC verification only if a secret is defined AND rawBody is present
if (WEBHOOK_SECRET && rawBody) {
  const signatureHeader = headers['x-signature'] || headers['X-Signature'] || '';
  if (signatureHeader) {
    const bodyStr = Buffer.isBuffer(rawBody) ? rawBody.toString('utf8') : rawBody;
    const expectedSignature = crypto
      .createHmac('sha256', WEBHOOK_SECRET)
      .update(bodyStr)
      .digest('hex');

    const received = Buffer.from(signatureHeader, 'utf8');
    const expected = Buffer.from(expectedSignature, 'utf8');

    if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) {
      throw new Error('SECURITY_ERROR: Invalid HMAC signature.');
    }
  }
}

return [{ json: { body, headers } }];

const body = $json.body;

if (!body || !body.event_type) throw new Error('Invalid webhook: missing event_type');
if (!body.event_data || !body.event_data.video_id) throw new Error('Invalid webhook: missing event_data.video_id');

const eventType = body.event_type;
const videoId = body.event_data.video_id;
const callbackId = body.event_data.callback_id || '';

if (eventType.includes('.fail') || eventType.includes('.error')) {
  throw new Error(`HEYGEN_FAIL_EVENT: Received ${eventType} for video_id=${videoId}`);
}

// CANONICAL EVENT FILTER: Only process the final captioned video event!
// Drops raw video & gif webhooks immediately in <5ms
if (eventType !== 'avatar_video_caption.success') {
  return []; 
}

const lockKey = `tavli:lock:${videoId}`;
return [{ json: { key: lockKey, eventType, videoId, callbackId, eventId: videoId, lockKey } }];

const inputItem = $input.first() ? $input.first().json : {};
const val = inputItem.value || inputItem.json?.value;
const upstream = $('Validate Canonical Event (avatar_video.success)1').item.json;

// Stop ONLY if Data Table explicitly holds 'PROCESSING' or 'DONE' for this videoId
if (val === 'PROCESSING' || val === 'DONE') {
  return []; // Lock acquired by another concurrent execution -> Stop silently
}

return [{ json: { ...upstream, lockValue: 'PROCESSING' } }];

const items = $input.all();
const upstream = $('Prep Get Job Correlation Key1').item.json.upstream;
const expectedJobId = upstream.callbackId;

let job = null;
for (const item of items) {
  const row = item.json || {};
  if (row.job_id === expectedJobId || row.post_text || row.script) {
    job = row;
    break;
  }
  const val = row.value || row.json?.value;
  if (val) {
    if (typeof val === 'object') {
      if (val.job_id === expectedJobId || val.post_text || val.script) {
        job = val;
        break;
      }
    } else if (typeof val === 'string') {
      try {
        const parsed = JSON.parse(val);
        if (parsed && (parsed.job_id === expectedJobId || parsed.post_text || parsed.script)) {
          job = parsed;
          break;
        }
      } catch(e) {}
    }
  }
}

let postText = '';
if (job) {
  postText = job.post_text || job.postText || job.script || '';
}

// Unstoppable Fallback: If Data Table record is missing during manual testing,
// fallback to a high-converting default caption so execution NEVER stops!
if (!postText) {
  postText = "Discover the pinnacle of rare elegance with TAVLI Diamonds. Craftsmanship defined by perfection.\n\nDM TAVLI Diamonds to learn more.\n\n#TAVLIDiamonds #Luxury #Diamonds #Exclusivity #HighJewelry";
}

const masterAccountIds = [
  '6a184670312a16c3f0256c7c_TrGytdd80tTYeMqrGW9e_813347731859277_page',
  '6a1846982bbb6fbb330688e3_TrGytdd80tTYeMqrGW9e_000Y4eMNplxtiH9XHEGPNPUyqvmATxc0n1_business',
  '6a196a8576455473847ec689_TrGytdd80tTYeMqrGW9e_UCztQtixZp-kIV-0lo9BMRtg_profile',
  '6a18470d530b7464136cf8dc_TrGytdd80tTYeMqrGW9e_882987208099842105_profile'
];

return [{ json: {
  videoId: upstream.videoId,
  jobId: expectedJobId || 'tavli_fallback_' + Date.now(),
  eventId: upstream.eventId,
  postText: postText,
  accountIds: masterAccountIds
} }];

const data = $json.data || {};
const status = data.status || 'unknown';
const ctx = $('Validate Correlation Context1').item.json;

if (status === 'failed') {
  throw new Error(`HEYGEN_FAILED: HeyGen video generation failed for video_id=${ctx.videoId}`);
}
if (status === 'processing' || status === 'pending') {
  throw new Error(`HEYGEN_STATE_MISMATCH: Webhook reported success but API returned status=${status} for video_id=${ctx.videoId}`);
}
if (status !== 'completed') {
  throw new Error(`HEYGEN_UNEXPECTED_STATUS: Status=${status} for video_id=${ctx.videoId}`);
}

const videoUrl = data.captioned_video_url || data.video_url || '';
if (!videoUrl) {
  throw new Error(`HEYGEN_NO_URL: No authoritative video_url returned for video_id=${ctx.videoId}`);
}

return [{ json: { ...ctx, videoUrl } }];

const inputItem = $input.first();
const bin = inputItem.binary;
if (!bin || !bin.data) throw new Error('Binary validation failed: no binary data received');

const originalMime = bin.data.mimeType || '';
const size = bin.data.fileSize || 0;
const fileName = bin.data.fileName || bin.data.fileExtension || '';
const isVideo = originalMime.startsWith('video/') || originalMime.includes('octet-stream') || originalMime.includes('binary') || fileName.toLowerCase().endsWith('.mp4');

if (!isVideo) throw new Error(`Binary validation failed: expected video/* or .mp4, got mime=${originalMime}, fileName=${fileName}`);
if (size < 102400) throw new Error(`Binary validation failed: file size ${size} bytes is below 100KB threshold (corruption guard)`);

// Normalize binary MIME type & filename for GHL upload compatibility (prevents Cloudflare 502 Bad Gateway)
const normalizedBinary = {
  ...bin,
  data: {
    ...bin.data,
    mimeType: 'video/mp4',
    fileName: 'tavli_video.mp4',
    fileExtension: 'mp4'
  }
};

const ctx = $('Verify Authoritative Video URL1').item.json;

return [{
  json: { ...ctx, mimeType: 'video/mp4', fileSize: size },
  binary: normalizedBinary,
  pairedItem: { item: 0 }
}];

const resp = $input.first().json;
const ghlUrl = resp.url || resp.fileUrl || '';
if (!ghlUrl) throw new Error('GHL upload failed: no media URL returned: ' + JSON.stringify(resp).substring(0, 300));
const ctx = $('Verify Authoritative Video URL1').item.json;
return [{ json: { ...ctx, ghlUrl } }];

const resp = $input.first().json;
const sc = resp.statusCode || 0;
const hdrs = resp.headers || {};
const ct = hdrs['content-type'] || '';
const cl = hdrs['content-length'];

if (sc < 200 || sc >= 300) throw new Error(`GHL permanent URL validation failed: HTTP ${sc}`);
if (!ct.startsWith('video/') && !ct.startsWith('application/octet-stream')) throw new Error(`GHL permanent URL validation failed: Content-Type=${ct}`);
if (cl !== undefined && parseInt(cl) === 0) throw new Error('GHL permanent URL validation failed: Content-Length=0');

const ctx = $('Extract GHL Permanent URL1').item.json;
return [{ json: { key: `tavli:job:${ctx.jobId}`, ctx } }];

const rawRow = $input.first().json;
const rawVal = rawRow.value || rawRow.json?.value;
const ctx = $('Check Permanent Media Validity1').item.json.ctx;
let job = {};
try { job = JSON.parse(rawVal); } catch(e) {}

const updatedJob = {
  ...job,
  ghl_media_url: ctx.ghlUrl,
  status: 'MEDIA_READY',
  updated_at: new Date().toISOString()
};

return [{ json: {
  key: `tavli:job:${ctx.jobId}`,
  value: JSON.stringify(updatedJob),
  ctx
} }];

const headers = $input.first().json.headers || {};
const reqKey = headers['x-tavli-recovery-key'] || headers['X-TAVLI-Recovery-Key'] || '';
const expectedKey = process.env.TAVLI_RECOVERY_KEY;

if (!expectedKey) {
  throw new Error('SECURITY_ERROR: TAVLI_RECOVERY_KEY environment variable is missing.');
}

if (reqKey !== expectedKey) {
  throw new Error('SECURITY_ERROR: Unauthorized recovery request.');
}

const body = $input.first().json.body || {};
const videoId = body.video_id || body.videoId || '';
const accountId = body.account_id || body.accountId || '';

if (!videoId) throw new Error('Validation failed: video_id is required for recovery');

return [{ json: { videoId, accountId, aliasKey: `tavli:video:${videoId}` } }];

const row = $input.first().json;
const aliasVal = row.value || row.json?.value;
const upstream = $('Authenticate Recovery Request (No Fallbacks)1').item.json;

if (!aliasVal) {
  throw new Error(`CORRELATION_MISSING: No Data Table video alias exists for video_id=${upstream.videoId}`);
}

let alias;
try {
  alias = JSON.parse(aliasVal);
} catch (e) {
  throw new Error(`CORRELATION_INVALID: Invalid video alias JSON for video_id=${upstream.videoId}`);
}

if (!alias || !alias.job_id) {
  throw new Error(`CORRELATION_INVALID: Data Table video alias has no job_id for video_id=${upstream.videoId}`);
}

return [{ json: { ...upstream, jobId: alias.job_id, jobKey: `tavli:job:${alias.job_id}` } }];

const posts = $input.first().json.posts || $input.first().json.results || $input.first().json.data || [];
const ctx = $('Extract Recovery Job ID (Fail-Fast)1').item.json;
const row = $('Data Table: Retrieve Recovery Job Context1').item.json;
const rawJob = row.value || row.json?.value;

let ghlUrl = '';
let jobVideoId = '';
try {
  const parsedJob = JSON.parse(rawJob);
  ghlUrl = parsedJob.ghl_media_url || '';
  jobVideoId = parsedJob.video_id || '';
} catch(e) {}

const videoId = ctx.videoId;
const accountId = ctx.accountId;

if (!ghlUrl) {
  throw new Error(`RECOVERY_ERROR: No ghl_media_url stored in Data Table job record for video_id=${videoId}. Cannot reconcile without permanent GHL media URL.`);
}

if (jobVideoId && jobVideoId !== videoId) {
  throw new Error(`CORRELATION_MISMATCH: Data Table job does not belong to requested video_id=${videoId} (found ${jobVideoId})`);
}

let match = null;
if (Array.isArray(posts)) {
  match = posts.find(p => {
    const media = p.media || [];
    const accs = p.accountIds || p.account_ids || [];
    const mediaMatch = media.some(m => m.url === ghlUrl);
    const accMatch = !accountId || accs.includes(accountId);
    return mediaMatch && accMatch;
  });
}

const totalFetched = Array.isArray(posts) ? posts.length : 0;
const hasMorePages = totalFetched >= 100;

return [{
  json: {
    status: match ? 'FOUND' : 'NOT_FOUND',
    videoId,
    accountId,
    existingPostId: match ? (match._id || match.id || match.postId) : null,
    searchCoverage: hasMorePages ? 'PARTIAL (First 100 posts searched)' : 'COMPLETE (All recent posts searched)',
    message: match
      ? `Post exists in GHL: ${match._id || match.id || match.postId}. No retry required.`
      : hasMorePages
        ? `No match found in first 100 posts. RETRY_CANDIDATE — operator verification recommended.`
        : `No match found in all ${totalFetched} recent posts. RETRY_CANDIDATE — safe for operator retry.`
  }
}];

